class Solution {
    public String nextClosestTime(String time) {
        int cur = Integer.parseInt(time.substring(0, 2)) * 60 + Integer.parseInt(time.substring(3, 5));
        Set<Character> allowed = new HashSet<>();
        for (char c : time.toCharArray()) if (c != ':') allowed.add(c);
        while (true) {
            cur = (cur + 1) % 1440;
            int h = cur / 60, m = cur % 60;
            String candidate = String.format("%02d:%02d", h, m);
            boolean valid = true;
            for (int i = 0; i < candidate.length(); i++) {
                if (i != 2 && !allowed.contains(candidate.charAt(i))) {
                    valid = false;
                    break;
                }
            }
            if (valid) return candidate;
        }
    }
}

var nextClosestTime = function(time) {
    let cur = parseInt(time.slice(0, 2), 10) * 60 + parseInt(time.slice(3, 5), 10);
    const allowed = new Set(time.replace(':', '').split(''));
    while (true) {
        cur = (cur + 1) % 1440;
        const h = Math.floor(cur / 60), m = cur % 60;
        const sh = String(h).padStart(2, '0');
        const sm = String(m).padStart(2, '0');
        const candidate = `${sh}:${sm}`;
        let valid = true;
        for (let i = 0; i < candidate.length; i++) {
            if (i !== 2 && !allowed.has(candidate[i])) {
                valid = false;
                break;
            }
        }
        if (valid) return candidate;
    }
};
